def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp_c = 0
    for a, b in history:
        if b == 'C':
            opp_c += 1
    opp_d = n - opp_c

    if opp_d == 0 and n >= 10:
        return 'D'

    opp_rate = opp_c / n
    my_last, opp_last = history[-1]

    if opp_rate <= 0.3:
        return 'D'

    if opp_last == 'D':
        if my_last == 'D':
            if opp_rate > 0.4:
                return 'C'
            return 'D'
        else:
            if opp_rate > 0.8:
                return 'C'
            return 'D'
    else:
        return 'C'
